import 'package:cloud_firestore/cloud_firestore.dart';import 'package:equatable/equatable.dart';enum NotificationType{message,call,appointment,reminder,system,update,promotion}class NotificationModel extends Equatable{final String id,userId;final String? chatId,callId,imageUrl,actionButtonText,actionRoute;final String title,body;final NotificationType type;final Map<String,dynamic>? data;final bool isRead,isSilent;final Timestamp? createdAt;const NotificationModel({required this.id,required this.userId,this.chatId,this.callId,required this.title,required this.body,required this.type,this.data,this.isRead=false,this.createdAt,this.imageUrl,this.actionButtonText,this.actionRoute,this.isSilent=false});factory NotificationModel.fromFirestore(String id,Map<String,dynamic>d)=>NotificationModel(id:id,userId:d['userId']??'',chatId:d['chatId'],callId:d['callId'],title:d['title']??'',body:d['body']??'',type:NotificationType.values.firstWhere((x)=>x.name==d['type'],orElse:()=>NotificationType.message),data:Map<String,dynamic>.from(d['data']??{}),isRead:d['isRead']??false,createdAt:d['createdAt'],imageUrl:d['imageUrl'],actionButtonText:d['actionButtonText'],actionRoute:d['actionRoute'],isSilent:d['isSilent']??false);Map<String,dynamic>toFirestore()=>{'userId':userId,'chatId':chatId,'callId':callId,'title':title,'body':body,'type':type.name,'data':data,'isRead':isRead,'createdAt':createdAt??FieldValue.serverTimestamp(),'imageUrl':imageUrl,'actionButtonText':actionButtonText,'actionRoute':actionRoute,'isSilent':isSilent};bool get isUnread=>!isRead;bool get isMessage=>type==NotificationType.message;bool get isCall=>type==NotificationType.call;@override List<Object?>get props=>[id,userId,chatId,callId,title,body,type,data,isRead,createdAt,imageUrl,actionButtonText,actionRoute,isSilent];}